import { GraphQLError } from "graphql";
import { Item, ItemChanges, ItemRepository } from "./repository";

export const ERROR_CODES = {
  notFound: "NOT_FOUND",
  notOwner: "NOT_OWNER",
  versionConflict: "VERSION_CONFLICT",
  badInput: "BAD_USER_INPUT",
} as const;

const MAX_LIST_LIMIT = 100;
const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Write-conflict rules for active/active replication (docs/architecture.md):
 *
 * - IDs are UUIDs generated by the database, so inserts on different clouds
 *   never collide.
 * - Each row is owned by the cloud that created it (`ownerCloud`). Only the
 *   owner cloud's API updates or deletes it; other clouds reject the request
 *   with NOT_OWNER so that the client can retry against the owner.
 * - Updates and deletes carry the version the client read; a mismatch is
 *   rejected with VERSION_CONFLICT (optimistic locking).
 */
export class ItemService {
  constructor(
    private readonly repository: ItemRepository,
    private readonly cloudId: string,
  ) {}

  get(id: string): Promise<Item | null> {
    assertUuid(id);
    return this.repository.findById(id);
  }

  list(limit: number, offset: number): Promise<Item[]> {
    if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIST_LIMIT) {
      throw badInput(`limit must be between 1 and ${MAX_LIST_LIMIT}`);
    }
    if (!Number.isInteger(offset) || offset < 0) {
      throw badInput("offset must be 0 or greater");
    }
    return this.repository.list(limit, offset);
  }

  create(name: string, description: string | null): Promise<Item> {
    if (name.trim() === "") {
      throw badInput("name must not be empty");
    }
    return this.repository.insert(name, description, this.cloudId);
  }

  async update(id: string, version: number, changes: ItemChanges): Promise<Item> {
    assertUuid(id);
    if (changes.name !== undefined && changes.name.trim() === "") {
      throw badInput("name must not be empty");
    }
    const updated = await this.repository.update(
      id,
      this.cloudId,
      version,
      changes,
    );
    if (updated) {
      return updated;
    }
    throw await this.explainRejectedWrite(id, version);
  }

  async delete(id: string, version: number): Promise<boolean> {
    assertUuid(id);
    if (await this.repository.delete(id, this.cloudId, version)) {
      return true;
    }
    throw await this.explainRejectedWrite(id, version);
  }

  /** Finds out why a conditional update / delete matched no row. */
  private async explainRejectedWrite(
    id: string,
    version: number,
  ): Promise<GraphQLError> {
    const current = await this.repository.findById(id);
    if (!current) {
      return new GraphQLError(`Item ${id} not found`, {
        extensions: { code: ERROR_CODES.notFound },
      });
    }
    if (current.ownerCloud !== this.cloudId) {
      return new GraphQLError(
        `Item ${id} is owned by ${current.ownerCloud}; send the request to that cloud`,
        {
          extensions: {
            code: ERROR_CODES.notOwner,
            ownerCloud: current.ownerCloud,
          },
        },
      );
    }
    return new GraphQLError(
      `Item ${id} has version ${current.version}, not ${version}`,
      {
        extensions: {
          code: ERROR_CODES.versionConflict,
          currentVersion: current.version,
        },
      },
    );
  }
}

const badInput = (message: string): GraphQLError =>
  new GraphQLError(message, { extensions: { code: ERROR_CODES.badInput } });

const assertUuid = (id: string): void => {
  if (!UUID_PATTERN.test(id)) {
    throw badInput("id must be a UUID");
  }
};
